class ConnectedWatershedTest{public static void main(String[]a){int n=96;float[] h=new float[n*n];for(int z=0;z<n;z++)for(int x=0;x<n;x++)h[z*n+x]=(float)(62+z*.10+Math.max(0,Math.abs(x-48)-4)*.20);var e=new EnvironmentMap(h);var r=RiverCourse.route(h,e,n,n,62,()->false,false,1,71,.18,.28);int side=80*n+75;if(r.flow().parent()[side]<0)throw new AssertionError("Gentle shoulder cannot connect");int connected=0;for(int start=0;start<h.length;start++){if(r.flow().parent()[start]<0)continue;int i=start,remaining=n*n;while(r.flow().parent()[i]>=0){int next=r.flow().parent()[i];double distance=Math.hypot(next%n-i%n,next/n-i/n);if(h[next]>h[i]+.051||(h[i]-h[next])/distance>.181)throw new AssertionError("Uphill or steep channel");if(--remaining==0)throw new AssertionError("Cyclic river");i=next;}if(h[i]>62)throw new AssertionError("Main river has no wet outlet");connected++;}if(connected<1000)throw new AssertionError("Missing watershed coverage");System.out.println("PASS: "+connected+" shoulder routes reach ocean, stay downhill and satisfy channel gradient limit");}}
